import json,hashlib
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).parent;root=out.parent;checks=[];manifest=json.loads((root/'evidence/version.json').read_text());assert manifest['version']=='core-journey-lowfi-v3'
def hashes():return {f:hashlib.sha256((root/f).read_bytes()).hexdigest()==h for f,h in manifest['sha256'].items()}
def note(name,data):checks.append({'check':name,'observed':data});(out/'v3-transport-review.json').write_text(json.dumps(checks,indent=2,ensure_ascii=False),encoding='utf-8');print(name,str(data)[:350],flush=True)
def times(page):return page.locator('#scene,#take-audio').evaluate_all('(es)=>es.map(e=>({id:e.id,t:e.currentTime,paused:e.paused,muted:e.muted,src:e.currentSrc}))')
def drag(page,tag):
 box=page.locator('#scrub').bounding_box();page.locator('#scrub').scroll_into_view_if_needed();box=page.locator('#scrub').bounding_box();rng=page.locator('#scrub').evaluate('(e)=>({value:+e.value,min:+e.min,max:+e.max})');frac=(rng['value']-rng['min'])/(rng['max']-rng['min']);y=box['y']+box['height']/2
 page.mouse.move(box['x']+8+(box['width']-16)*frac,y);page.mouse.down();page.mouse.move(box['x']+box['width']*.42,y,steps=8);t=times(page);page.wait_for_timeout(500);held=times(page);assert all(e['paused'] for e in held);assert abs(held[0]['t']-t[0]['t'])<.05;note(tag+' drag held pauses without time advance',{'down':t,'held':held});page.screenshot(path=str(out/('v3-review-'+tag+'-drag-held.png')));page.mouse.up();page.wait_for_timeout(220);released=times(page);assert not released[0]['paused'];assert abs(released[0]['t']-2.142)<.5
 if tag=='candidate':assert not released[1]['paused'] and abs(released[0]['t']-released[1]['t'])<.12 and released[0]['muted']
 else:assert released[1]['paused'] and not released[0]['muted']
 note(tag+' release plays sought correct source',released)
def pause_resume(page,tag):
 page.locator('#pause').click();expect(page.locator('#pause')).to_have_text('Resume');before=times(page);page.wait_for_timeout(260);assert abs(times(page)[0]['t']-before[0]['t'])<.05;page.screenshot(path=str(out/('v3-review-'+tag+'-resume.png')));page.locator('#pause').click();expect(page.locator('#pause')).to_have_text('Pause');page.wait_for_timeout(200);after=times(page);assert .08<after[0]['t']-before[0]['t']<.6;note(tag+' Resume retains paused position',{'before':before,'after':after})
assert all(hashes().values())
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':1440,'height':900},device_scale_factor=1);errs=[];page.on('pageerror',lambda e:errs.append(str(e)));page.goto('http://127.0.0.1:5178');page.wait_for_function('document.querySelector("#scene").readyState>=3');note('environment',{'version':manifest['version'],'browser':b.version,'dpr':1,'zoom':'100%','os':'Windows','date':'2026-10-27'});assert 'Recording ends automatically with this line.' not in page.locator('body').inner_text()
 page.locator('#process-again').click();expect(page.locator('#feedback')).to_contain_text('outside this prototype');note('Process again intentional utility remains boundary',page.locator('#feedback').inner_text())
 page.locator('#replay').click();page.wait_for_timeout(650);pause_resume(page,'original');drag(page,'original');page.locator('#replay').click();assert page.locator('#scene').evaluate('(e)=>e.currentTime<.3 && !e.paused');note('Replay while playing restarts',times(page))
 page.locator('#record').click();expect(page.locator('#capture-badge')).to_be_visible();assert page.locator('#pause').is_hidden();assert page.locator('#scrub').is_disabled();clock=page.locator('#scene').evaluate('(e)=>e.currentTime');page.locator('#scrub').scroll_into_view_if_needed();box=page.locator('#scrub').bounding_box();page.mouse.move(box['x']+box['width']*.2,box['y']+box['height']/2);page.mouse.down();page.mouse.move(box['x']+box['width']*.9,box['y']+box['height']/2,steps=5);page.mouse.up();page.locator('#scrub').evaluate('(e)=>e.focus()');focus=page.evaluate('document.activeElement.id');assert focus!='scrub';page.keyboard.press('Home');page.keyboard.press('ArrowRight');page.keyboard.press('End');after=page.locator('#scene').evaluate('(e)=>e.currentTime');assert 0<=after-clock<1.5;assert page.locator('#pause').is_hidden();note('Capture rejects pointer and keyboard seek and has no Pause',{'before':clock,'after':after,'focus':focus,'disabled':True});page.wait_for_function('!document.querySelector("#take").disabled',timeout=10000)
 identity=page.evaluate('JSON.parse(localStorage.getItem("dubbed-lowfi-v1")).candidates[0].id');page.locator('#take').click();page.wait_for_timeout(650);pause_resume(page,'candidate');drag(page,'candidate');assert page.evaluate('JSON.parse(localStorage.getItem("dubbed-lowfi-v1")).candidates[0].id')==identity;note('Candidate identity unaffected by transport',True)
 page.locator('#replay').click();page.wait_for_function('document.querySelector("#scene").paused && document.querySelector("#scene").currentTime>=5',timeout=10000);page.locator('#replay').click();assert page.locator('#scene').evaluate('(e)=>e.currentTime<.3 && !e.paused');note('Replay after fixed window end restarts',True)
 note('page errors',errs);assert not errs;note('stable hashes',hashes());assert all(hashes().values());b.close()

